"""R1 (лексика): BM25 по name + description с нормализацией текста.

Контракт runner арены: stdin {"input", "assets_dir"} -> stdout {"answer": "<JSON-массив до 3 id>"}.
Только стандартная библиотека; источник знаний — только каталог `<assets_dir>/catalog.jsonl`.

Изменения относительно baseline (см. README.md кандидата):
  1. список служебных слов (стоп-слова) убирается из запроса и из документов;
  2. собственный стеммер Портера (без внешних пакетов) на обеих сторонах;
  3. k1 = 1.2 (было 1.5);
  4. слова запроса вне словаря каталога заменяются ближайшим словом каталога (одна правка Дамерау-Левенштейна,
     длина слова от 6) с весом 0.7 — защита от опечаток;
  5. к BM25 (нормированному на максимум по запросу) добавляется 0.6 * косинус tf-idf по символьным триграммам слов.
"""
import json
import math
import re
import sys
from collections import Counter
from pathlib import Path

K1, B, TOP = 1.2, 0.75, 3
FUZZY, FUZZY_MIN = 0.7, 6  # вес слова, исправленного по словарю каталога; минимальная длина слова
NGRAM = 0.6                # вес косинуса tf-idf по символьным триграммам (0 — выключено)

STOP = frozenset(
    "a an and are as at be but by can could do does for from had has have how i if in into is it its just me my "
    "of on or our so some than that the their them then there these they this to up us was we were what when "
    "where which who why will with would you your pls please plz need want like get let help also any all about "
    "out over using use via".split()
)


class Porter:
    """Стеммер Портера (1980), собственная реализация; кэш по слову."""

    def __init__(self):
        self.cache = {}

    @staticmethod
    def _cons(w, i):
        c = w[i]
        if c in "aeiou":
            return False
        if c == "y":
            return i == 0 or not Porter._cons(w, i - 1)
        return True

    @classmethod
    def _m(cls, w):
        n, i, size = 0, 0, len(w)
        while i < size and cls._cons(w, i):
            i += 1
        while i < size:
            while i < size and not cls._cons(w, i):
                i += 1
            if i >= size:
                break
            n += 1
            while i < size and cls._cons(w, i):
                i += 1
        return n

    @classmethod
    def _vowel(cls, w):
        return any(not cls._cons(w, i) for i in range(len(w)))

    @classmethod
    def _dc(cls, w):
        return len(w) >= 2 and w[-1] == w[-2] and cls._cons(w, len(w) - 1)

    @classmethod
    def _cvc(cls, w):
        size = len(w)
        return (size >= 3 and cls._cons(w, size - 1) and not cls._cons(w, size - 2)
                and cls._cons(w, size - 3) and w[-1] not in "wxy")

    def stem(self, w):
        r = self.cache.get(w)
        if r is None:
            r = self.cache[w] = self._stem(w)
        return r

    S2 = [("ational", "ate"), ("tional", "tion"), ("enci", "ence"), ("anci", "ance"), ("izer", "ize"),
          ("abli", "able"), ("alli", "al"), ("entli", "ent"), ("eli", "e"), ("ousli", "ous"),
          ("ization", "ize"), ("ation", "ate"), ("ator", "ate"), ("alism", "al"), ("iveness", "ive"),
          ("fulness", "ful"), ("ousness", "ous"), ("aliti", "al"), ("iviti", "ive"), ("biliti", "ble")]
    S3 = [("icate", "ic"), ("ative", ""), ("alize", "al"), ("iciti", "ic"), ("ical", "ic"), ("ful", ""), ("ness", "")]
    S4 = sorted(["al", "ance", "ence", "er", "ic", "able", "ible", "ant", "ement", "ment", "ent", "ion", "ou",
                 "ism", "ate", "iti", "ous", "ive", "ize"], key=len, reverse=True)

    def _stem(self, w):
        if len(w) <= 2 or not w.isalpha():
            return w
        m, V, dc, cvc = self._m, self._vowel, self._dc, self._cvc
        if w.endswith("sses"):
            w = w[:-2]
        elif w.endswith("ies"):
            w = w[:-2]
        elif w.endswith("ss"):
            pass
        elif w.endswith("s"):
            w = w[:-1]
        flag = False
        if w.endswith("eed"):
            if m(w[:-3]) > 0:
                w = w[:-1]
        elif w.endswith("ed") and V(w[:-2]):
            w, flag = w[:-2], True
        elif w.endswith("ing") and V(w[:-3]):
            w, flag = w[:-3], True
        if flag:
            if w.endswith(("at", "bl", "iz")):
                w += "e"
            elif dc(w) and w[-1] not in "lsz":
                w = w[:-1]
            elif m(w) == 1 and cvc(w):
                w += "e"
        if w.endswith("y") and V(w[:-1]):
            w = w[:-1] + "i"
        for a, b in self.S2:
            if w.endswith(a):
                if m(w[:-len(a)]) > 0:
                    w = w[:-len(a)] + b
                break
        for a, b in self.S3:
            if w.endswith(a):
                if m(w[:-len(a)]) > 0:
                    w = w[:-len(a)] + b
                break
        for a in self.S4:
            if w.endswith(a):
                st = w[:-len(a)]
                if m(st) > 1 and (a != "ion" or (st and st[-1] in "st")):
                    w = st
                break
        if w.endswith("e"):
            st = w[:-1]
            if m(st) > 1 or (m(st) == 1 and not cvc(st)):
                w = st
        if m(w) > 1 and dc(w) and w.endswith("l"):
            w = w[:-1]
        return w


PORTER = Porter()


def words(text: str) -> list[str]:
    return re.findall(r"[a-z0-9]+", text.lower())


def tokenize(text: str) -> list[str]:
    ws = words(text)
    kept = [t for t in ws if t not in STOP]
    return [PORTER.stem(t) for t in (kept or ws)]


def near(a: str, b: str) -> bool:
    """Расстояние Дамерау-Левенштейна не больше 1 (замена, вставка, удаление, перестановка соседних)."""
    if a == b:
        return True
    la, lb = len(a), len(b)
    if abs(la - lb) > 1:
        return False
    if la == lb:
        diff = [i for i in range(la) if a[i] != b[i]]
        if len(diff) == 1:
            return True
        return len(diff) == 2 and diff[1] == diff[0] + 1 and a[diff[0]] == b[diff[1]] and a[diff[1]] == b[diff[0]]
    if la > lb:
        a, b = b, a
    i = 0
    while i < len(a) and a[i] == b[i]:
        i += 1
    return a[i:] == b[i + 1:]


def trigrams(word: str) -> list[str]:
    w = f"^{word}$"
    return [w[i:i + 3] for i in range(len(w) - 2)]


class Catalog:
    """Лексический словарь каталога: нужен для исправления опечаток и символьных триграмм."""

    def __init__(self, catalog: list[dict]):
        self.freq = Counter()
        gram_docs = []
        for c in catalog:
            grams = Counter()
            for w in words(c["name"] + " " + c["description"]):
                self.freq[w] += 1
                if w not in STOP:
                    grams.update(trigrams(w))
            gram_docs.append(grams)
        self.vocab = [w for w in self.freq if len(w) >= 4 and w not in STOP]
        df = Counter(g for d in gram_docs for g in d)
        n = len(catalog)
        self.gidf = {g: math.log(1 + n / f) for g, f in df.items()}
        self.gvec = []
        for d in gram_docs:
            v = {g: (1 + math.log(c)) * self.gidf[g] for g, c in d.items()}
            norm = math.sqrt(sum(x * x for x in v.values())) or 1.0
            self.gvec.append({g: x / norm for g, x in v.items()})

    def correct(self, w: str) -> str | None:
        """Ближайшее по написанию слово каталога (одна правка), чаще встречающееся выигрывает."""
        if len(w) < FUZZY_MIN or not w.isalpha():
            return None
        near_words = [v for v in self.vocab if near(w, v)]
        same_first = [v for v in near_words if v[0] == w[0]]
        cands = same_first or near_words
        return max(cands, key=lambda v: self.freq[v]) if cands else None

    def cosine(self, query: str) -> list[float]:
        grams = Counter()
        for w in words(query):
            if w not in STOP:
                grams.update(trigrams(w))
        v = {g: (1 + math.log(c)) * self.gidf.get(g, 0.0) for g, c in grams.items()}
        norm = math.sqrt(sum(x * x for x in v.values())) or 1.0
        return [sum(x * d.get(g, 0.0) for g, x in v.items()) / norm for d in self.gvec]


class BM25:
    def __init__(self, docs: list[list[str]]):
        self.tfs = [Counter(d) for d in docs]
        self.lens = [len(d) for d in docs]
        self.avg = sum(self.lens) / len(docs)
        df = Counter(t for d in docs for t in set(d))
        n = len(docs)
        self.idf = {t: math.log(1 + (n - f + 0.5) / (f + 0.5)) for t, f in df.items()}

    def scores(self, query: list[str], weight: dict[str, float]) -> list[float]:
        out = []
        for tf, length in zip(self.tfs, self.lens):
            s = 0.0
            for t in query:
                if t in tf:
                    s += weight[t] * self.idf[t] * tf[t] * (K1 + 1) / (tf[t] + K1 * (1 - B + B * length / self.avg))
            out.append(s)
        return out


def query_terms(query: str, index: BM25, cat: Catalog) -> tuple[list[str], dict[str, float]]:
    """Токены запроса; слово вне словаря каталога заменяется ближайшим словом каталога с весом FUZZY."""
    ws = words(query)
    ws = [t for t in ws if t not in STOP] or ws
    out, weight = [], {}
    for w in ws:
        st = PORTER.stem(w)
        if st in index.idf:
            out.append(st)
            weight[st] = 1.0
        elif FUZZY:
            fixed = cat.correct(w)
            st2 = PORTER.stem(fixed) if fixed else None
            if st2 in index.idf:
                out.append(st2)
                weight[st2] = max(weight.get(st2, 0.0), FUZZY)
        else:
            out.append(st)
            weight[st] = 1.0
    return out, weight


def solve(task: dict) -> str:
    catalog = [json.loads(line) for line in (Path(task["assets_dir"]) / "catalog.jsonl").open(encoding="utf-8")]
    index = BM25([tokenize(c["name"] + " " + c["description"]) for c in catalog])
    cat = Catalog(catalog)
    qt, weight = query_terms(task["input"], index, cat)
    scores = index.scores(qt, weight)
    if NGRAM:
        top = max(scores) or 1.0
        scores = [s / top + NGRAM * c for s, c in zip(scores, cat.cosine(task["input"]))]
    # при равенстве — порядок каталога, чтобы ответ был детерминированным
    ranked = sorted(range(len(catalog)), key=lambda i: (-scores[i], i))
    return json.dumps([catalog[i]["id"] for i in ranked[:TOP]])


if __name__ == "__main__":
    print(json.dumps({"answer": solve(json.load(sys.stdin))}))
#!/usr/bin/env python3
"""build: эмбеддинги каталога (один раз) выбранным bi-encoder.

stdin  — {"assets_dir": "/assets", "build_dir": "/output", ...}
/output — emb.npy (N x D, L2-норма), ids.json, config.json (для solve), report.json (диагностика).
Документы кодирует sentence-transformers (эталон). numpy-энкодер (его использует solve, чтобы не импортировать torch)
сверяется с эталоном на тестовых запросах и нескольких документах; при расхождении solve использует sentence-transformers.
"""
import json
import os
import sys
import time
from pathlib import Path

os.environ.setdefault("TOKENIZERS_PARALLELISM", "false")
sys.path.insert(0, str(Path(__file__).resolve().parent))

import numpy as np  # noqa: E402

from enc import Encoder  # noqa: E402

PROBES = ["convert a pdf file to markdown", "i need something that reads my calendar and books meetings",
          "geocode a list of addresses", "pls summarise this long github issue thread for me"]


def main() -> None:
    task = json.load(sys.stdin)
    assets, out = Path(task["assets_dir"]), Path(task["build_dir"])
    out.mkdir(parents=True, exist_ok=True)
    p = json.loads((Path(__file__).resolve().parent / "params.json").read_text())
    catalog = [json.loads(line) for line in (assets / "catalog.jsonl").open(encoding="utf-8") if line.strip()]
    docs = [p["doc_prefix"] + p["doc_template"].format(name=c["name"], description=c["description"]) for c in catalog]
    model_dir = assets / "models" / p["model"]
    report = {"model": p["model"], "n_docs": len(docs)}

    t = time.time()
    from sentence_transformers import SentenceTransformer
    st = SentenceTransformer(str(model_dir), device="cpu")
    emb = st.encode(docs, normalize_embeddings=True, batch_size=32).astype(np.float32)
    report["reference_seconds"] = round(time.time() - t, 2)

    ok = False
    try:
        t = time.time()
        t1 = time.time()
        enc = Encoder(model_dir, p["pooling"], p["max_len"])
        report["numpy_load_seconds"] = round(time.time() - t1, 3)
        t1 = time.time()
        enc.encode([p["query_prefixes"][0] + PROBES[0]])
        report["numpy_one_query_seconds"] = round(time.time() - t1, 3)
        queries = [pre + q for pre in p["query_prefixes"] for q in PROBES]
        qn = enc.encode(queries)
        qref = st.encode(queries, normalize_embeddings=True, batch_size=32)
        sample = list(range(0, len(docs), 12))
        dn = enc.encode([docs[i] for i in sample])
        cos_q, cos_d = (qn * qref).sum(1), (dn * emb[sample]).sum(1)
        report["min_cos_queries"] = float(cos_q.min())
        report["min_cos_docs_sample"] = float(cos_d.min())
        report["probe_rank_equal"] = bool((np.argsort(-(qn @ emb.T), 1)[:, :5] == np.argsort(-(qref @ emb.T), 1)[:, :5]).all())
        ok = bool(cos_q.min() > 0.999 and cos_d.min() > 0.999)
        report["numpy_check_seconds"] = round(time.time() - t, 2)
    except Exception as exc:
        report["numpy_error"] = repr(exc)
    report["numpy_encoder_ok"] = ok

    np.save(out / "emb.npy", emb)
    (out / "ids.json").write_text(json.dumps([c["id"] for c in catalog]))
    (out / "config.json").write_text(json.dumps({**p, "numpy_encoder_ok": ok}))
    (out / "report.json").write_text(json.dumps(report, indent=1))
    print(json.dumps(report))


if __name__ == "__main__":
    main()
"""Энкодер BERT на numpy: токенайзер `tokenizers` + веса safetensors, без torch и transformers.

Нужен, чтобы одноразовый контейнер solve не платил за импорт torch (секунды) ради кодирования одного короткого запроса.
Совпадение с sentence-transformers проверяет build (report.json).
v2: веса читаются последовательно (без page-fault по memmap), без импорта scipy (erf — полином Абрамовица-Стегана).
"""
import json
import math
import struct
from pathlib import Path

import numpy as np

_DT = {"F32": np.float32, "F16": np.float16}
_SKIP = ("pooler.", "position_ids")


def read_safetensors(path):
    """Читает safetensors без зависимостей: заголовок JSON + сырые байты, последовательное чтение нужных тензоров."""
    out = {}
    with open(path, "rb") as f:
        n = struct.unpack("<Q", f.read(8))[0]
        header = json.loads(f.read(n))
        base = 8 + n
        items = sorted(((k, v) for k, v in header.items() if k != "__metadata__" and v["dtype"] in _DT
                        and not any(s in k for s in _SKIP)), key=lambda kv: kv[1]["data_offsets"][0])
        for k, v in items:
            a, b = v["data_offsets"]
            f.seek(base + a)
            buf = np.frombuffer(f.read(b - a), dtype=_DT[v["dtype"]]).reshape(v["shape"])
            out[k] = buf.astype(np.float32, copy=False)
    return out


def _erf(x):
    # Abramowitz-Stegun 7.1.26, |ошибка| < 1.5e-7
    s = np.sign(x)
    a = np.abs(x)
    t = 1.0 / (1.0 + 0.3275911 * a)
    poly = ((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592
    return s * (1.0 - poly * t * np.exp(-a * a))


def _gelu(x):
    return 0.5 * x * (1.0 + _erf(x * np.float32(1 / math.sqrt(2))))


def _ln(x, w, b, eps):
    mu = x.mean(-1, keepdims=True)
    var = ((x - mu) ** 2).mean(-1, keepdims=True)
    return (x - mu) / np.sqrt(var + eps) * w + b


class Encoder:
    def __init__(self, model_dir, pooling, max_len=512):
        from tokenizers import Tokenizer
        model_dir = Path(model_dir)
        cfg = json.loads((model_dir / "config.json").read_text())
        self.heads = cfg["num_attention_heads"]
        self.layers = cfg["num_hidden_layers"]
        self.eps = cfg.get("layer_norm_eps", 1e-12)
        self.pooling = pooling
        self.tok = Tokenizer.from_file(str(model_dir / "tokenizer.json"))
        self.tok.enable_truncation(max_length=max_len)
        self.tok.enable_padding(pad_id=self.tok.token_to_id("[PAD]") or 0, pad_token="[PAD]")
        self.w = read_safetensors(model_dir / "model.safetensors")

    def _layer(self, x, mask_bias, i):
        w, p = self.w, f"encoder.layer.{i}."
        B, T, H = x.shape
        d = H // self.heads

        def lin(name, h):
            return h @ w[p + name + ".weight"].T + w[p + name + ".bias"]

        def split(h):
            return h.reshape(B, T, self.heads, d).transpose(0, 2, 1, 3)

        q, k, v = split(lin("attention.self.query", x)), split(lin("attention.self.key", x)), split(lin("attention.self.value", x))
        att = q @ k.transpose(0, 1, 3, 2) / math.sqrt(d) + mask_bias
        att = np.exp(att - att.max(-1, keepdims=True))
        att /= att.sum(-1, keepdims=True)
        ctx = (att @ v).transpose(0, 2, 1, 3).reshape(B, T, H)
        x = _ln(lin("attention.output.dense", ctx) + x, w[p + "attention.output.LayerNorm.weight"], w[p + "attention.output.LayerNorm.bias"], self.eps)
        h = _gelu(lin("intermediate.dense", x))
        return _ln(lin("output.dense", h) + x, w[p + "output.LayerNorm.weight"], w[p + "output.LayerNorm.bias"], self.eps)

    def encode(self, texts, batch=16):
        out = []
        for s in range(0, len(texts), batch):
            encs = self.tok.encode_batch(texts[s: s + batch])
            ids = np.array([e.ids for e in encs], dtype=np.int64)
            mask = np.array([e.attention_mask for e in encs], dtype=np.float32)
            w = self.w
            x = w["embeddings.word_embeddings.weight"][ids] + w["embeddings.position_embeddings.weight"][: ids.shape[1]][None] \
                + w["embeddings.token_type_embeddings.weight"][0][None, None]
            x = _ln(x, w["embeddings.LayerNorm.weight"], w["embeddings.LayerNorm.bias"], self.eps).astype(np.float32)
            mask_bias = ((1.0 - mask) * -1e9)[:, None, None, :].astype(np.float32)
            for i in range(self.layers):
                x = self._layer(x, mask_bias, i)
            if self.pooling == "cls":
                e = x[:, 0]
            else:
                e = (x * mask[:, :, None]).sum(1) / np.maximum(mask.sum(1, keepdims=True), 1e-9)
            out.append(e / np.maximum(np.linalg.norm(e, axis=1, keepdims=True), 1e-12))
        return np.concatenate(out).astype(np.float32)
{
  "model": "bge-base-en-v1.5",
  "pooling": "cls",
  "max_len": 512,
  "query_prefixes": ["", "Represent this sentence for searching relevant passages: "],
  "doc_prefix": "",
  "doc_template": "{name}. {description}"
}
#!/usr/bin/env python3
"""solve: кодирует только запрос, топ-3 по косинусу к эмбеддингам каталога из <assets_dir>/prepared.

stdin  — {"input": "<запрос>", "assets_dir": "/assets"}
stdout — {"answer": "<JSON-массив до 3 id>"}
Читает: /assets/prepared (emb.npy, ids.json, config.json) и модель /assets/models/<name>. Каталог не нужен.
"""
import json
import os
import sys
from pathlib import Path

os.environ.setdefault("TOKENIZERS_PARALLELISM", "false")
sys.path.insert(0, str(Path(__file__).resolve().parent))

import numpy as np  # noqa: E402

TOP = 3


def encode_queries(texts: list, cfg: dict, model_dir: Path):
    if cfg.get("numpy_encoder_ok"):
        try:
            from enc import Encoder
            return Encoder(model_dir, cfg["pooling"], cfg["max_len"]).encode(texts)
        except Exception as exc:
            print(f"numpy encoder failed, fallback: {exc!r}", file=sys.stderr)
    from sentence_transformers import SentenceTransformer
    return SentenceTransformer(str(model_dir), device="cpu").encode(texts, normalize_embeddings=True)


def solve(task: dict) -> str:
    assets = Path(task["assets_dir"])
    prepared = assets / "prepared"
    cfg = json.loads((prepared / "config.json").read_text())
    ids = json.loads((prepared / "ids.json").read_text())
    emb = np.load(prepared / "emb.npy")
    texts = [prefix + task["input"] for prefix in cfg["query_prefixes"]]
    q = encode_queries(texts, cfg, assets / "models" / cfg["model"])
    scores = (emb @ q.T).mean(axis=1)  # среднее косинусов по вариантам запроса
    ranked = sorted(range(len(ids)), key=lambda i: (-float(scores[i]), i))
    return json.dumps([ids[i] for i in ranked[:TOP]])


if __name__ == "__main__":
    print(json.dumps({"answer": solve(json.load(sys.stdin))}))
# r2-04: bge-base-en-v1.5, ансамбль вариантов запроса (без инструкции + с инструкцией BGE)

Родители: r2-01 (без инструкции: acc@1 0.700, recall@3 83.0%, score 0.7345), r2-02 (с инструкцией: acc@1 0.685, recall@3 88.5%, score 0.7395). r2-03 (bge-small) отброшен: 0.694.

## Гипотеза
